```js
// build/build-data.mjs   —   node --max-old-space-size=8192 build/build-data.mjs
// deps: npm i kuromoji   (only build-time dep; nothing ships to the browser)
import fs from 'node:fs';
import fsp from 'node:fs/promises';
import path from 'node:path';
import zlib from 'node:zlib';
import { execFileSync } from 'node:child_process';
import kuromoji from 'kuromoji';

const JM_TAG   = '3.6.2+20260914172325';
const JM_TAGQ  = encodeURIComponent(JM_TAG);            // '+' -> %2B in the TAG segment only
const JM_REL   = `https://github.com/scriptin/jmdict-simplified/releases/download/${JM_TAGQ}`;
const KVG_TAG  = 'r20250816';
const CACHE    = 'build/.cache';
const OUT      = 'app/data';
const LEVELS   = [5, 4, 3, 2, 1];

// ---------------------------------------------------------------- fetch+cache
async function grab(url, name) {
  const dst = path.join(CACHE, name);
  if (fs.existsSync(dst)) return dst;
  await fsp.mkdir(CACHE, { recursive: true });
  const r = await fetch(url, { redirect: 'follow' });
  if (!r.ok) throw new Error(`${r.status} ${url}`);
  await fsp.writeFile(dst, Buffer.from(await r.arrayBuffer()));
  console.log(`  fetched ${name} (${fs.statSync(dst).size} B)`);
  return dst;
}
const unzipTo = (zip, dir) => { execFileSync('unzip', ['-o', '-q', zip, '-d', dir]); return dir; };
const readJSON = f => JSON.parse(fs.readFileSync(f, 'utf8'));

// --------------------------------------------------------------- tiny CSV rdr
function csv(text) {
  const rows = []; let f = '', row = [], q = false;
  for (let i = 0; i < text.length; i++) { const c = text[i];
    if (q) { if (c === '"') { if (text[i+1] === '"') { f += '"'; i++; } else q = false; } else f += c; }
    else if (c === '"') q = true;
    else if (c === ',') { row.push(f); f = ''; }
    else if (c === '\n') { row.push(f); f = ''; rows.push(row); row = []; }
    else if (c !== '\r') f += c;
  }
  if (f || row.length) { row.push(f); rows.push(row); }
  return rows;
}

const KANA_ONLY = /^[぀-ゟ゠-ヿーー・]+$/;
const NON_KANA  = /[^぀-ゟ゠-ヿーー・]/;
const kata2hira = s => s.replace(/[ァ-ヶ]/g, c => String.fromCharCode(c.charCodeAt(0) - 0x60));

// ================================================================ MAIN
const tokenizer = await new Promise((res, rej) =>
  kuromoji.builder({ dicPath: './node_modules/kuromoji/dict' })
          .build((e, t) => e ? rej(e) : res(t)));       // ~3.9 s, one time

// ---- 1. sources -------------------------------------------------------------
const vocabRaw = {}, kanjiRaw = {};
for (const L of LEVELS) {
  vocabRaw[L] = readJSON(await grab(
    `https://raw.githubusercontent.com/evanclan/OpenJLPT/main/data/json/vocab/n${L}.json`, `vocab-n${L}.json`));
  kanjiRaw[L] = readJSON(await grab(
    `https://raw.githubusercontent.com/evanclan/OpenJLPT/main/data/json/kanji/n${L}.json`, `kanji-n${L}.json`));
}

// ---- 2. JPDB frequency ranks  (8294/8334 coverage) --------------------------
unzipTo(await grab(
  'https://raw.githubusercontent.com/Kuuuube/yomitan-dictionaries/main/dictionaries/JPDB_v2.2_Frequency_2024-10-13.zip',
  'jpdb.zip'), `${CACHE}/jpdb`);
const rank = new Map();
for (const [term, , v] of readJSON(`${CACHE}/jpdb/term_meta_bank_1.json`)) {
  const n = v?.value ?? v?.frequency?.value;            // two shapes exist in this file
  if (n != null && !rank.has(term)) rank.set(term, n);
}

// ---- 3. kanjium pitch accent  (8194/8334 coverage) --------------------------
const pitchByWord = new Map(), pitchByRead = new Map();
for (const line of fs.readFileSync(await grab(
      'https://raw.githubusercontent.com/mifunetoshiro/kanjium/master/data/source_files/raw/accents.txt',
      'accents.txt'), 'utf8').split('\n')) {
  const [w, r, a] = line.split('\t'); if (!w) continue;
  (pitchByWord.get(w) ?? pitchByWord.set(w, []).get(w)).push([r, a]);
  if (r) (pitchByRead.get(r) ?? pitchByRead.set(r, []).get(r)).push([w, a]);
}

// ---- 4. Anki decks: reading repair + a level-disagreement report ------------
const ankiRead = new Map(), ankiLevel = new Map();
for (const L of LEVELS) {
  const rows = csv(fs.readFileSync(await grab(
    `https://raw.githubusercontent.com/jamsinclair/open-anki-jlpt-decks/main/src/n${L}.csv`, `anki-n${L}.csv`), 'utf8'));
  rows.shift();
  for (const r of rows) { if (!r[0]) continue; if (r[1]) ankiRead.set(r[0], r[1]); ankiLevel.set(r[0], L); }
}

// ---- 5. jmdict-examples -> backfill the 889 example-less rows (656 fillable)
unzipTo(await grab(`${JM_REL}/jmdict-examples-eng-${JM_TAG}.json.zip`, 'jmdict-examples.zip'), CACHE);
const exBySurface = new Map();
for (const w of readJSON(`${CACHE}/jmdict-examples-eng-3.6.2.json`).words) {
  const forms = [...w.kanji.map(k => k.text), ...w.kana.map(k => k.text)];
  for (const s of w.sense) for (const e of s.examples ?? []) {
    const ja = e.sentences.find(x => x.lang === 'jpn')?.text;
    const en = e.sentences.find(x => x.lang === 'eng')?.text;
    if (!ja || !en) continue;
    for (const f of forms) {
      const a = exBySurface.get(f) ?? exBySurface.set(f, []).get(f);
      if (a.length < 3) a.push({ ja, en });
    }
  }
}

// ---- 6. normalise + enrich + sort ------------------------------------------
const tok = s => tokenizer.tokenize(s).map(t => [
  t.surface_form,
  (t.basic_form && t.basic_form !== '*' && t.basic_form !== t.surface_form) ? t.basic_form : 0,
  t.reading ? kata2hira(t.reading) : 0,                 // hiragana, ready for <ruby>
]);

const report = { badReading: [], crossLevel: [], noExample: [], levelDisagree: [] };
const seenWord = new Map();

for (const L of LEVELS) {
  const out = [];
  for (const w of vocabRaw[L]) {
    // (a) split the 20 slash-joined multi-form headwords
    const forms = w.word.split(/\s*[\/／]\s*/).map(s => s.trim()).filter(Boolean);
    const word = forms[0], alt = forms.slice(1);

    // (b) repair the 27 corrupt readings: 「（感）」 / 「なん/なに」 / 「Uӣ[い」
    let reading = (w.reading ?? '').trim();
    if (reading && NON_KANA.test(reading)) {
      report.badReading.push({ level: L, word, raw: reading });
      reading = reading.split(/[\/／\s、]/)[0].trim();
      if (NON_KANA.test(reading)) reading = ankiRead.get(word) ?? '';
    }
    // (c) OpenJLPT rule: reading is empty IFF the word is kana-only (verified 0 exceptions)
    if (!reading) reading = KANA_ONLY.test(word)
      ? word
      : (ankiRead.get(word) ?? kata2hira(tokenizer.tokenize(word).map(t => t.reading ?? t.surface_form).join('')));

    // (d) flag the 243 cross-level collisions instead of silently merging them
    const prev = seenWord.get(word);
    if (prev) report.crossLevel.push({ word, a: prev, b: { level: L, reading, meanings: w.meanings } });
    else seenWord.set(word, { level: L, reading, meanings: w.meanings });

    if (ankiLevel.has(word) && ankiLevel.get(word) !== L)
      report.levelDisagree.push({ word, openjlpt: L, anki: ankiLevel.get(word) });

    // (e) pitch: word+reading -> word -> reading
    let pitch = null;
    const cw = pitchByWord.get(word);
    if (cw) pitch = (cw.find(x => x[0] === reading) ?? cw[0])[1];
    if (pitch == null && pitchByRead.has(reading)) pitch = pitchByRead.get(reading)[0][1];

    // (f) examples: OpenJLPT first (median 11 chars, 100% contain the headword), then backfill
    let exs = (w.examples ?? []).slice(0, 2);
    if (!exs.length) {
      exs = (exBySurface.get(word) ?? exBySurface.get(reading) ?? []).slice(0, 2);
      if (!exs.length) report.noExample.push({ level: L, word });
    }

    out.push({
      w: word, alt, r: reading, m: w.meanings,
      f: rank.get(word) ?? rank.get(reading) ?? null,   // JPDB rank
      p: pitch,                                          // '0' | '1' | '2,4' | null
      ex: exs.map(e => ({ j: e.ja, e: e.en, t: tok(e.ja) })),
    });
  }
  out.sort((a, b) => (a.f ?? 9e5) - (b.f ?? 9e5));       // MOST USEFUL FIRST
  writeOut(`vocab/n${L}.json`, out);
}

// ---- 7. kanji: OpenJLPT + KanjiVG strokes + KanjiVG components -------------
const kvgGz  = await grab(`https://github.com/KanjiVG/kanjivg/releases/download/${KVG_TAG}/kanjivg-${KVG_TAG.slice(1)}.xml.gz`, 'kanjivg.xml.gz');
const kvgXml = zlib.gunzipSync(fs.readFileSync(kvgGz)).toString('utf8');
const strokes = {}, comps = {};
for (const m of kvgXml.matchAll(/<kanji id="kvg:kanji_([0-9a-f]+)">([\s\S]*?)<\/kanji>/g)) {
  const ch = String.fromCodePoint(parseInt(m[1].split('-')[0], 16));
  if (strokes[ch]) continue;
  strokes[ch] = [...m[2].matchAll(/ d="([^"]+)"/g)]
    .map(x => x[1].replace(/-?\d+\.\d+/g, n => (+n).toFixed(1)));   // 1.90MB -> 1.59MB
  const els = [...new Set([...m[2].matchAll(/kvg:element="([^"]+)"/g)].map(x => x[1]))].filter(x => x !== ch);
  const rad = m[2].match(/kvg:element="([^"]+)"[^>]*kvg:radical="general"/)?.[1] ?? null;
  comps[ch] = { c: els, r: rad };
}
const kanjiOut = [];
for (const L of LEVELS) for (const c of kanjiRaw[L]) {
  kanjiOut.push({ k: c.character, l: L, s: c.strokes, g: c.grade, f: c.freq,
                  on: c.onyomi, kun: c.kunyomi, m: c.meanings, cp: comps[c.character]?.c ?? [], rad: comps[c.character]?.r ?? null });
}
kanjiOut.sort((a, b) => (a.f ?? 9e4) - (b.f ?? 9e4));
writeOut('kanji/all.json', kanjiOut);
const n54 = new Set(kanjiOut.filter(k => k.l >= 4).map(k => k.k));
writeOut('kanji/strokes-core.json', Object.fromEntries(Object.entries(strokes).filter(([k]) => n54.has(k))));
writeOut('kanji/strokes-rest.json', Object.fromEntries(
  kanjiOut.filter(k => !n54.has(k.k)).map(k => [k.k, strokes[k.k]])));

// ---- 8. tap-a-word dictionary: jmdict-eng-common compacted -----------------
unzipTo(await grab(`${JM_REL}/jmdict-eng-common-${JM_TAG}.json.zip`, 'jmdict-common.zip'), CACHE);
const POS = { v5u:'v5',v5k:'v5',v5s:'v5',v5t:'v5',v5n:'v5',v5b:'v5',v5m:'v5',v5r:'v5','vs-i':'vs' };
const dict = [], surfaceIdx = {};
for (const w of readJSON(`${CACHE}/jmdict-eng-common-3.6.2.json`).words) {
  const kj = (w.kanji.filter(x => x.common).length ? w.kanji.filter(x => x.common) : w.kanji).slice(0,3).map(x => x.text);
  const kn = (w.kana .filter(x => x.common).length ? w.kana .filter(x => x.common) : w.kana ).slice(0,3).map(x => x.text);
  const senses = w.sense.slice(0,3).map(s => [
    [...new Set(s.partOfSpeech.map(p => POS[p] ?? p))].slice(0,2).join(','),
    s.gloss.slice(0,4).map(g => g.text).join('; '),
    ...(s.misc[0] ? [s.misc[0]] : []),
  ]);
  const i = dict.push([w.id, kj.join('|'), kn.join('|'), senses]) - 1;
  for (const s of [...kj, ...kn]) (surfaceIdx[s] ??= []).push(i);
}
writeOut('dict/common.json', dict);        // measured 1.95 MB raw / 560 KB br
writeOut('dict/index.json',  surfaceIdx);  // measured 0.53 MB raw / 250 KB gz
// optional: same loop over jmdict-eng, then shard by cp % 64 (largest shard 195 KB gz)

fs.writeFileSync('build/data-report.json', JSON.stringify(report, null, 2));
console.log(`report: ${report.badReading.length} bad readings, ${report.crossLevel.length} cross-level collisions, ` +
            `${report.noExample.length} still without an example, ${report.levelDisagree.length} level disagreements`);

// ---------------------------------------------------------------- write+compress
function writeOut(rel, obj) {
  const p = path.join(OUT, rel);
  fs.mkdirSync(path.dirname(p), { recursive: true });
  const buf = Buffer.from(JSON.stringify(obj));
  fs.writeFileSync(p, buf);
  fs.writeFileSync(p + '.br', zlib.brotliCompressSync(buf,
    { params: { [zlib.constants.BROTLI_PARAM_QUALITY]: 11 } }));   // serve .br if the host supports it
  fs.writeFileSync(p + '.gz', zlib.gzipSync(buf, { level: 9 }));
  console.log(`  ${rel}  ${(buf.length/1024)|0}KB raw`);
}
```

### 4. RUNTIME SNIPPET — tap-a-word on a pre-tokenized sentence

```js
// ex.t is [[surface, lemma|0, hiraganaReading|0], ...] baked at build time.
function renderSentence(ex, { furigana }) {
  const frag = document.createDocumentFragment();
  for (const [surface, lemma, reading] of ex.t) {
    const el = document.createElement('span');
    el.className = 'tk';
    if (furigana && reading && reading !== surface && /[一-鿿]/.test(surface)) {
      const ruby = document.createElement('ruby');
      ruby.append(surface, Object.assign(document.createElement('rt'), { textContent: reading }));
      el.append(ruby);
    } else el.textContent = surface;
    el.dataset.q = (lemma || surface);          // the JMdict lookup key
    frag.append(el);
  }
  return frag;
}
// one delegated listener on the container:
container.addEventListener('click', e => {
  const t = e.target.closest('.tk'); if (!t) return;
  player?.pause();                              // pause the video on tap
  openWordSheet(t.dataset.q);                   // -> dict/index.json -> dict/common.json
});
```

