const JPOD_PLACEHOLDER_BYTES = 52288;   // verified: identical md5 7e2c2f954ef6 for 3 nonsense inputs
async function hasJpodAudio(word, reading) {
  const u = `https://assets.languagepod101.com/dictionary/japanese/audiomp3.php`
          + `?kanji=${encodeURIComponent(word)}&kana=${encodeURIComponent(reading)}`;
  const r = await fetch(u);
  if (!r.ok) return false;
  return (await r.arrayBuffer()).byteLength !== JPOD_PLACEHOLDER_BYTES;
}
// NOTE: you MUST send both kanji= and kana=. Sending kana= alone returned the placeholder for ねこ.
```

